[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param(
 [ValidateSet('Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback')][string]$Action='Check',
 [string]$StatePath="$env:ProgramData\Lacksan\EXP-065-hpsysinfo-state.json",
 [string]$LogPath="$env:ProgramData\Lacksan\EXP-065-hpsysinfo-events.jsonl"
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$Experiment='EXP-065';$Provider='hp-system-info-hsa-manual';$ServiceName='HPSysInfoCap'
$ProtectedServices=@('WinDefend','mpssvc','wuauserv','UsoSvc','BITS','TermService','Tailscale')
function Write-Event([string]$Event,[string]$Result,$Before=$null,$After=$null,[string]$Reason=$null,[string]$Failure=$null){if([string]::IsNullOrWhiteSpace($LogPath)){return};$p=Split-Path -Parent $LogPath;if($p-and!(Test-Path $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null};[ordered]@{schemaVersion=1;timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment=$Experiment;provider=$Provider;machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;action=$Action;event=$Event;result=$Result;before=$Before;after=$After;refusalReason=$Reason;failureDetail=$Failure;evidenceStatus='needs-evidence'}|ConvertTo-Json -Compress -Depth 20|Add-Content -LiteralPath $LogPath -Encoding UTF8}
function Test-Elevated{([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)}
function Get-Hash([string]$Text){$s=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($s.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)))).Replace('-','')}finally{$s.Dispose()}}
function Same($A,$B){($A|ConvertTo-Json -Compress -Depth 20)-eq($B|ConvertTo-Json -Compress -Depth 20)}
function Resolve-Exe([string]$PathName){$m=[regex]::Match([Environment]::ExpandEnvironmentVariables($PathName),'^\s*(?:"(?<p>[^"]+\.exe)"|(?<p>[^\s]+\.exe))');if(!$m.Success){return $null};[IO.Path]::GetFullPath($m.Groups['p'].Value)}
function Get-FileIdentity([string]$Path){if(!(Test-Path -LiteralPath $Path -PathType Leaf)){return $null};$f=Get-Item $Path;$sig=Get-AuthenticodeSignature $Path;$pub=if($sig.SignerCertificate){$sig.SignerCertificate.Subject}else{$null};[pscustomobject]@{Path=$f.FullName;Sha256=(Get-FileHash $Path -Algorithm SHA256).Hash;FileVersion=$f.VersionInfo.FileVersion;ProductVersion=$f.VersionInfo.ProductVersion;CompanyName=$f.VersionInfo.CompanyName;SignatureStatus=$sig.Status.ToString();Publisher=$pub;Thumbprint=if($sig.SignerCertificate){$sig.SignerCertificate.Thumbprint}else{$null};HPSigned=($sig.Status-eq'Valid'-and$pub-match'(?i)HP Inc|Hewlett-Packard')}}
function Get-ManagementState{$cs=Get-CimInstance Win32_ComputerSystem;$ccm=[bool](Get-Service CcmExec -ErrorAction SilentlyContinue);$en=@(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Enrollments' -ErrorAction SilentlyContinue|Where-Object{$_.PSChildName-match'^[0-9A-Fa-f-]{36}$'}).Count;$om=@(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Provisioning\OMADM\Accounts' -ErrorAction SilentlyContinue|Where-Object{$_.PSChildName-match'^[0-9A-Fa-f-]{36}$'}).Count;[pscustomobject]@{Managed=([bool]$cs.PartOfDomain-or$ccm-or($en-gt0-and$om-gt0));DomainJoined=[bool]$cs.PartOfDomain;ConfigMgr=$ccm;EnrollmentCount=$en;OmadmCount=$om}}
function Get-Delayed{$p="HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName";$v=Get-ItemProperty $p -Name DelayedAutoStart -ErrorAction SilentlyContinue;[pscustomobject]@{Exists=($null-ne$v);Value=if($null-ne$v){[int]$v.DelayedAutoStart}else{$null}}}
function Get-ServiceState{$svc=Get-CimInstance Win32_Service -Filter "Name='$ServiceName'" -ErrorAction SilentlyContinue;if(!$svc){return $null};$g=Get-Service $ServiceName;$reg=Get-Item "HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName";[pscustomobject]@{Name=$svc.Name;DisplayName=$svc.DisplayName;StartMode=$svc.StartMode;State=$svc.State;StartName=$svc.StartName;PathName=$svc.PathName;DelayedAutoStart=Get-Delayed;Dependencies=@($g.ServicesDependedOn|Select-Object -ExpandProperty Name|Sort-Object);Dependents=@($g.DependentServices|Select-Object -ExpandProperty Name|Sort-Object);Recovery=((& sc.exe qfailure $ServiceName 2>&1|Out-String).Trim());Triggers=((& sc.exe qtriggerinfo $ServiceName 2>&1|Out-String).Trim());RegistryOwner=(Get-Acl $reg.PSPath).Owner}}
function Get-ProtectedConfiguration{@($ProtectedServices|ForEach-Object{Get-CimInstance Win32_Service -Filter "Name='$_'" -ErrorAction SilentlyContinue}|Where-Object{$_}|Sort-Object Name|Select-Object Name,StartMode,PathName)}
function Get-Support{$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$mg=Get-ManagementState;$st=Get-ServiceState;$reasons=@();$id=$null;if($os.Caption-notmatch'Windows 11'){$reasons+='Windows 11 required.'};if($cs.Manufacturer-notmatch'(?i)^HP$|Hewlett-Packard'){$reasons+='HP platform required.'};if(!(Test-Elevated)){$reasons+='Elevation required.'};if($mg.Managed){$reasons+='Enterprise management ownership detected.'};if(!$st){$reasons+='HPSysInfoCap service required.'}else{$exe=Resolve-Exe $st.PathName;$id=if($exe){Get-FileIdentity $exe}else{$null};if($st.DisplayName-notmatch'(?i)HP System Info HSA Service'){$reasons+='Unexpected service display identity.'};if(!$id-or!$id.HPSigned){$reasons+='Valid HP-signed executable required.'};if($st.StartMode-eq'Disabled'){$reasons+='Disabled service refused.'};if($st.Dependents.Count-gt0){$reasons+='Dependent services make this candidate dependency-sensitive.'}};[pscustomobject]@{Supported=($reasons.Count-eq0);Reasons=$reasons;OS=$os.Caption;Build=$os.BuildNumber;Manufacturer=$cs.Manufacturer;Model=$cs.Model;Elevated=(Test-Elevated);Management=$mg;ServiceState=$st;Executable=$id;EvidenceStatus='needs-evidence'}}
function Save-State($s){if(!$s.Supported){throw($s.Reasons-join' ')};if(Test-Path $StatePath){throw 'State overwrite refused.'};$p=Split-Path -Parent $StatePath;if($p-and!(Test-Path $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null};$protected=Get-ProtectedConfiguration;$o=[ordered]@{schemaVersion=1;experiment=$Experiment;provider=$Provider;capturedUtc=(Get-Date).ToUniversalTime().ToString('o');capturedBootUtc=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o');machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;original=$s.ServiceState;executable=$s.Executable;management=$s.Management;protectedHash=Get-Hash($protected|ConvertTo-Json -Compress -Depth 20);evidenceStatus='needs-evidence'};$o|ConvertTo-Json -Depth 20|Set-Content $StatePath -Encoding UTF8;[pscustomobject]$o}
function Read-State{if(!(Test-Path $StatePath)){throw 'Captured state required.'};$s=Get-Content $StatePath -Raw|ConvertFrom-Json;$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;if($s.schemaVersion-ne1-or$s.experiment-ne$Experiment-or$s.provider-ne$Provider-or$s.machine-ne$env:COMPUTERNAME-or$s.userSid-ne$sid){throw 'State identity validation failed.'};$s}
function Assert-DriftFree($s){if((Get-ManagementState).Managed){throw 'Management ownership drift detected.'};$now=Get-ServiceState;if(!$now){throw 'Service identity drift detected.'};$id=Get-FileIdentity (Resolve-Exe $now.PathName);if(!$id-or!$id.HPSigned-or$id.Sha256-ne[string]$s.executable.Sha256-or$id.Thumbprint-ne[string]$s.executable.Thumbprint){throw 'Executable identity drift detected.'};if(!(Same $now.Dependencies $s.original.Dependencies)-or!(Same $now.Dependents $s.original.Dependents)-or$now.PathName-ne[string]$s.original.PathName-or$now.StartName-ne[string]$s.original.StartName-or$now.Recovery-ne[string]$s.original.Recovery-or$now.Triggers-ne[string]$s.original.Triggers){throw 'Service configuration drift detected.'};if((Get-Hash((Get-ProtectedConfiguration)|ConvertTo-Json -Compress -Depth 20))-ne[string]$s.protectedHash){throw 'Protected configuration drift detected.'};$now}
function Set-Manual{$out=& sc.exe config $ServiceName start= demand 2>&1;if($LASTEXITCODE-ne0){throw("sc.exe config failed: "+($out-join' '))};$p="HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName";Remove-ItemProperty $p -Name DelayedAutoStart -ErrorAction SilentlyContinue}
function Test-Treatment{$s=Get-ServiceState;$s.StartMode-eq'Manual'-and!$s.DelayedAutoStart.Exists}
function Restore-State($s){$start=if($s.original.StartMode-eq'Auto'){'auto'}elseif($s.original.StartMode-eq'Manual'){'demand'}else{throw 'Unsupported original startup mode.'};$out=& sc.exe config $ServiceName start= $start 2>&1;if($LASTEXITCODE-ne0){throw("startup rollback failed: "+($out-join' '))};$p="HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName";if($s.original.DelayedAutoStart.Exists){New-ItemProperty $p -Name DelayedAutoStart -PropertyType DWord -Value ([int]$s.original.DelayedAutoStart.Value) -Force|Out-Null}else{Remove-ItemProperty $p -Name DelayedAutoStart -ErrorAction SilentlyContinue};$svc=Get-Service $ServiceName;if([string]$s.original.State-eq'Running'-and$svc.Status-ne'Running'){Start-Service $ServiceName}elseif([string]$s.original.State-ne'Running'-and$svc.Status-eq'Running'){Stop-Service $ServiceName -Force:$false}}
try{$support=Get-Support;Write-Event 'support-detection' $(if($support.Supported){'pass'}else{'refused'}) $null $support ($(if($support.Supported){$null}else{$support.Reasons-join' '}));switch($Action){'Check'{$support};'Capture'{$s=Save-State $support;Write-Event 'capture' 'pass' $null $s;$s};'DryRun'{if(!$support.Supported){throw($support.Reasons-join' ')};$r=[pscustomobject]@{WouldChange=$true;MutationCount=1;ServiceName=$ServiceName;TargetStartMode='Manual';PreserveCurrentRunningState=$true;RebootPersistenceRequired=$true;HPSystemInfoFunctionalCheck='needs-evidence';Rollback='Restore exact captured startup mode, delayed-auto-start state, and original running state after drift checks.';EvidenceStatus='needs-evidence'};Write-Event 'dry-run' 'pass' $support.ServiceState $r;$r};'Apply'{$s=if(Test-Path $StatePath){Read-State}else{Save-State $support};$before=Assert-DriftFree $s;if(Test-Treatment){Write-Event 'apply' 'idempotent' $before $before;return [pscustomobject]@{Applied=$true;MutationCount=0}};$running=([string]$before.State-eq'Running');if($WhatIfPreference){Write-Event 'apply' 'whatif' $before $before;return [pscustomobject]@{Applied=$false;WhatIf=$true;MutationCount=0}};if($PSCmdlet.ShouldProcess($ServiceName,'Change HP System Info HSA Service startup mode to Manual while preserving running state')){Set-Manual}else{return};$after=Get-ServiceState;if(!(Test-Treatment)-or$running-ne([string]$after.State-eq'Running')){throw 'Application verification failed.'};Write-Event 'apply' 'pass' $before $after;$after};'Verify'{$s=Read-State;$before=Assert-DriftFree $s;if(!(Test-Treatment)){throw 'Treatment verification failed.'};$r=[pscustomobject]@{Verified=$true;Service=$before;HPSystemInfoWorkflow='needs-evidence';DeviceManager='needs-evidence';ProtectedApplicationReadiness='needs-evidence'};Write-Event 'verify' 'pass' $before $r;$r};'VerifyReboot'{$s=Read-State;$boot=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime();if($boot-le[datetime]$s.capturedBootUtc){throw 'A later boot is required.'};$before=Assert-DriftFree $s;if(!(Test-Treatment)){throw 'Reboot persistence failed.'};$r=[pscustomobject]@{VerifiedReboot=$true;BootUtc=$boot.ToString('o');Service=$before;DemandStart='needs-evidence';HPSystemInfoWorkflow='needs-evidence';ProtectedApplicationReadiness='needs-evidence'};Write-Event 'verify-reboot' 'pass' $before $r;$r};'Rollback'{$s=Read-State;$before=Assert-DriftFree $s;if($before.StartMode-eq[string]$s.original.StartMode-and(Same $before.DelayedAutoStart $s.original.DelayedAutoStart)-and$before.State-eq[string]$s.original.State){Write-Event 'rollback' 'idempotent' $before $before;return [pscustomobject]@{RolledBack=$true;MutationCount=0}};if(!(Test-Treatment)){throw 'Rollback collision detected; treatment state changed.'};if($WhatIfPreference){Write-Event 'rollback' 'whatif' $before $before;return [pscustomobject]@{RolledBack=$false;WhatIf=$true;MutationCount=0}};if($PSCmdlet.ShouldProcess($ServiceName,'Restore exact EXP-065 service startup and running state')){Restore-State $s}else{return};$after=Get-ServiceState;if($after.StartMode-ne[string]$s.original.StartMode-or!(Same $after.DelayedAutoStart $s.original.DelayedAutoStart)-or$after.State-ne[string]$s.original.State){throw 'Exact rollback verification failed.'};Write-Event 'rollback' 'pass' $before $after;$after}}}catch{Write-Event 'failure' 'failure' $null $null $null $_.Exception.Message;throw}